// Corrections for names that are spelled wrong in the vault but should be
// right on the public site. The Obsidian plugin keeps re-sending the original
// permalinks, so they are fixed at build time instead of in each note.
// Old URLs keep working through the pages generated by src/site/redirects.11ty.js.

const PERMALINK_FIXES = {
  "/productivtiy/": "/productivity/",
};

const FOLDER_NAME_FIXES = {
  "Productivtiy": "Productivity",
};

function fixPermalink(permalink) {
  if (typeof permalink !== "string") {
    return permalink;
  }
  for (const [from, to] of Object.entries(PERMALINK_FIXES)) {
    if (permalink.startsWith(from)) {
      return to + permalink.substring(from.length);
    }
  }
  return permalink;
}

function fixFolderName(name) {
  return FOLDER_NAME_FIXES[name] || name;
}

exports.fixPermalink = fixPermalink;
exports.fixFolderName = fixFolderName;
